DROP TABLE IF EXISTS `sync_pesanan_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sync_pesanan_data` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sheet_name` varchar(255) DEFAULT NULL,
  `tanggal` varchar(255) DEFAULT NULL,
  `nama_outlet` varchar(255) DEFAULT NULL,
  `nama_produk` varchar(255) DEFAULT NULL,
  `jumlah` varchar(255) DEFAULT NULL,
  `satuan` varchar(255) DEFAULT NULL,
  `total_faktur` varchar(255) DEFAULT NULL,
  `terkirim` varchar(255) DEFAULT NULL,
  `belum_terkirim` varchar(255) DEFAULT NULL,
  `persen_terpenuhi` varchar(255) DEFAULT NULL,
  `persen_belum_terpenuhi` varchar(255) DEFAULT NULL,
  `keterangan` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sync_pesanan_data_nama_outlet_index` (`nama_outlet`),
  KEY `sync_pesanan_data_tanggal_index` (`tanggal`)
) ENGINE=InnoDB AUTO_INCREMENT=3683 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
