DROP TABLE IF EXISTS `vehicles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vehicles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `license_plate` varchar(255) NOT NULL,
  `chassis_number` varchar(255) DEFAULT NULL,
  `brand_type` varchar(255) DEFAULT NULL,
  `manufacture_year` int(11) DEFAULT NULL,
  `color` varchar(255) DEFAULT NULL,
  `capacity` varchar(255) DEFAULT NULL,
  `photo` varchar(255) DEFAULT NULL,
  `annual_tax_date` date DEFAULT NULL,
  `five_year_tax_date` date DEFAULT NULL,
  `plate_replacement_date` date DEFAULT NULL,
  `stnk_expiry_date` date DEFAULT NULL,
  `kir_expiry_date` date DEFAULT NULL,
  `insurance_policy` varchar(255) DEFAULT NULL,
  `insurance_expiry_date` date DEFAULT NULL,
